import React, { useMemo } from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type CinematicVerseProps = Record<string, any>;

// Custom Sun Icon component matching the reference
const SunIcon: React.FC<{ size: number; color: string; style?: React.CSSProperties }> = ({ size, color, style }) => {
  return (
    <svg width={size} height={size} viewBox="0 0 40 40" style={style}>
      {/* Central ring */}
      <circle cx="20" cy="20" r="7" fill="none" stroke={color} strokeWidth="4" />
      
      {/* 8 Rays */}
      {Array.from({ length: 8 }).map((_, i) => (
        <g key={i} transform={`rotate(${i * 45} 20 20)`}>
          <polygon points="20,2 23,7 17,7" fill={color} />
        </g>
      ))}
    </svg>
  );
};

const CinematicVerse: React.FC<CinematicVerseProps> = ({
  backgroundColor = "#121110",
  transparentBackground = false,
  durationInSeconds = 15,
  cardColor = "#111111",
  textColor = "#FFFFFF",
  mutedTextColor = "#A3A3A3",
  accentColor = "#FFFFFF",
  headerText = "VERSE OF THE DAY",
  referenceText = "Matthew 28:18–19 NIV",
  verseText = "Then Jesus came to them and said, \"All authority in heaven and on earth has been given to me. Therefore go and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit.\"",
  glowOpacity = 0.15,
}) => {
  useFontLoader(["Inter", "Playfair Display"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Layout math based on 9:16 vertical orientation mostly, but responsive
  const s = Math.min(width, height);
  const cardWidth = width * 0.88;
  const padding = cardWidth * 0.08;
  const borderRadius = s * 0.06;

  const headerFontSize = s * 0.035;
  const referenceFontSize = s * 0.045;
  const bodyFontSize = s * 0.06;
  const iconSize = s * 0.07;

  // Animations
  const cardIntroStart = 10;
  const textIntroStart = 30;

  // Cinematic continuous drift
  const cardScale = interpolate(frame, [0, durationInSeconds * fps], [0.95, 1.02], {
    extrapolateRight: "clamp",
  });

  const cardOpacity = interpolate(frame, [cardIntroStart, cardIntroStart + 30], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const cardY = spring({
    frame: frame - cardIntroStart,
    fps,
    config: { damping: 14, mass: 1.2 },
    durationInFrames: 60,
  });
  const cardTranslateY = interpolate(cardY, [0, 1], [50, 0]);

  // Header Animation
  const headerOpacity = interpolate(frame, [textIntroStart, textIntroStart + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  // Icon Animation
  const iconRotation = interpolate(frame, [textIntroStart, textIntroStart + 60], [-90, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const iconScale = spring({
    frame: frame - textIntroStart,
    fps,
    config: { damping: 12 },
  });

  // Word splitting for kinetic typography
  const words = useMemo(() => verseText.split(" "), [verseText]);
  const wordStaggerFrames = 4; // Frames between each word appearing

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
        fontFamily: "Inter, sans-serif",
      }}
    >
      {/* Cinematic subtle background glow */}
      {!transparentBackground && (
        <div
          style={{
            position: "absolute",
            width: s * 1.5,
            height: s * 1.5,
            borderRadius: "50%",
            background: `radial-gradient(circle, ${cardColor} 0%, transparent 70%)`,
            opacity: glowOpacity,
            transform: `scale(${cardScale * 1.1})`,
            transition: "none",
          }}
        />
      )}

      {/* Main Card */}
      <div
        style={{
          width: cardWidth,
          backgroundColor: cardColor,
          borderRadius: borderRadius,
          padding: padding,
          boxShadow: "0 20px 40px rgba(0,0,0,0.4), inset 0 1px 1px rgba(255,255,255,0.05)",
          display: "flex",
          flexDirection: "column",
          gap: padding * 0.8,
          opacity: cardOpacity,
          transform: `scale(${cardScale}) translateY(${cardTranslateY}px)`,
          transition: "none",
        }}
      >
        {/* Header Section */}
        <div
          style={{
            display: "flex",
            alignItems: "flex-start",
            gap: padding * 0.5,
            opacity: headerOpacity,
            transition: "none",
          }}
        >
          {/* Icon Column */}
          <div style={{ paddingTop: s * 0.005 }}>
            <SunIcon 
              size={iconSize} 
              color={accentColor} 
              style={{
                transform: `rotate(${iconRotation}deg) scale(${iconScale})`,
                transition: "none"
              }} 
            />
          </div>

          {/* Text Column */}
          <div style={{ display: "flex", flexDirection: "column", gap: s * 0.005 }}>
            <div
              style={{
                fontSize: headerFontSize,
                fontWeight: 600,
                letterSpacing: "0.08em",
                color: mutedTextColor,
                textTransform: "uppercase",
                transition: "none",
              }}
            >
              {headerText}
            </div>
            <div
              style={{
                fontSize: referenceFontSize,
                fontWeight: 500,
                color: textColor,
                letterSpacing: "-0.01em",
                transition: "none",
              }}
            >
              {referenceText}
            </div>
          </div>
        </div>

        {/* Verse Body Section */}
        <div
          style={{
            fontFamily: "'Playfair Display', serif",
            fontSize: bodyFontSize,
            color: textColor,
            lineHeight: 1.45,
            fontWeight: 400,
            display: "flex",
            flexWrap: "wrap",
            gap: "0.25em 0.3em", // Adjust gap for word spacing
            transition: "none",
          }}
        >
          {words.map((word, i) => {
            const wordStartFrame = textIntroStart + 20 + i * wordStaggerFrames;
            
            const wordOpacity = interpolate(
              frame,
              [wordStartFrame, wordStartFrame + 15],
              [0, 1],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }
            );

            const wordY = interpolate(
              frame,
              [wordStartFrame, wordStartFrame + 15],
              [15, 0],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }
            );

            const wordBlur = interpolate(
              frame,
              [wordStartFrame, wordStartFrame + 15],
              [10, 0],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }
            );

            return (
              <span
                key={i}
                style={{
                  opacity: wordOpacity,
                  transform: `translateY(${wordY}px)`,
                  filter: `blur(${wordBlur}px)`,
                  display: "inline-block",
                  transition: "none",
                  willChange: "transform, opacity, filter",
                }}
              >
                {word}
              </span>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CinematicVerse;